/**
 * Phase C — Content Manifest Interface (C1)
 * 
 * Single source of truth for all pages generated by Content OS.
 * Supports deep content generation with 2000+ words per page.
 * v1.0.0 - Frozen
 */

import { z } from 'zod';

// Schema for content manifest validation
export const ContentManifestSchema = z.object({
  // Core identifiers
  id: z.string().uuid(),
  slug: z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/),
  type: z.enum([
    'agent',
    'category',
    'comparison',
    'research',
    'mcp_server',
    'pillar',
    'governance',
    'pricing'
  ]),

  // Routing
  path: z.string().startsWith('/'),
  canonicalPath: z.string().startsWith('/'),

  // Content
  title: z.string().min(1),
  description: z.string().min(1),
  summary: z.string().optional(),
  content: z.string().optional(),

  // Entity relationship
  entityId: z.string().optional(),
  entityType: z.enum([
    'agent',
    'category',
    'comparison',
    'research',
    'mcp_server',
    'author'
  ]).optional(),

  // SEO
  priority: z.number().min(0).max(1).optional(),
  changeFrequency: z.enum([
    'always', 'hourly', 'daily', 'weekly', 'monthly', 'yearly', 'never'
  ]).optional(),

  // Metadata
  createdAt: z.string().datetime(),
  updatedAt: z.string().datetime(),
  publishedAt: z.string().datetime().optional(),
  contentType: z.string().optional(),

  // Quality
  qualityScore: z.number().min(0).max(100).optional(),
  evidenceScore: z.number().min(0).max(100).optional(),

  // State
  status: z.enum([
    'draft',
    'in_review',
    'published',
    'archived',
    'needs_update'
  ]).default('draft'),

  // Relationships
  relatedEntities: z.array(z.string()).optional(),
  redirectFrom: z.array(z.string()).optional(),

  // Versioning
  version: z.string().regex(/^\d+\.\d+\.\d+$/),
  schemaVersion: z.string().default('1.0.0'),

  // Deep content extensions
  deepContent: z.object({
    targetWordCount: z.number().min(1500).max(10000),
    sections: z.array(z.object({
      id: z.string(),
      title: z.string(),
      wordCount: z.number(),
      content: z.string().optional(),
      subSections: z.array(z.object({
        id: z.string(),
        title: z.string(),
        wordCount: z.number(),
        content: z.string().optional()
      })).optional()
    })).optional(),
    faq: z.array(z.object({
      question: z.string(),
      answer: z.string()
    })).optional(),
    references: z.array(z.string()).optional()
  }).optional()
});

export type ContentManifest = z.infer<typeof ContentManifestSchema>;

export interface ContentSection {
  id: string;
  title: string;
  order: number;
  requiredWordCount: number;
  tags: string[];
  description: string;
  deepContent?: string;
}

export interface ContentTemplate {
  id: string;
  name: string;
  version: string;
  sections: ContentSection[];
  defaultSections: string[];
  targetWordCount: number;
}

